// Get top URLs by impressions and inspect them
const accessToken = $input.first().json.access_token;
const propertyUrl = $('Loop Properties').first().json.property_url;

// 1. Get top URLs by impressions (last 90d)
const endDate = new Date();
endDate.setDate(endDate.getDate() - 3);
const startDate = new Date(endDate);
startDate.setDate(startDate.getDate() - 90);

const searchResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://searchconsole.googleapis.com/webmasters/v3/sites/${encodeURIComponent(propertyUrl)}/searchAnalytics/query`,
  headers: {'Authorization': `Bearer ${accessToken}`},
  body: {
    startDate: startDate.toISOString().split('T')[0],
    endDate: endDate.toISOString().split('T')[0],
    dimensions: ['page'],
    rowLimit: 2000,
  },
});

const urls = (searchResponse.rows || [])
  .sort((a, b) => b.impressions - a.impressions)
  .slice(0, 2000)
  .map(r => r.keys[0]);

// 2. Inspect each URL (with rate limiting)
const results = [];
for (let i = 0; i < urls.length; i++) {
  try {
    const inspectResponse = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://searchconsole.googleapis.com/v1/urlInspection/index:inspect`,
      headers: {'Authorization': `Bearer ${accessToken}`},
      body: {
        inspectionUrl: urls[i],
        siteUrl: propertyUrl,
      },
    });
    results.push({
      property_url: propertyUrl,
      url: urls[i],
      inspection_result: inspectResponse,
    });
  } catch (e) {
    // Skip failed inspections
  }
  // Rate limit: ~2 req/sec
  if (i % 2 === 1) await new Promise(r => setTimeout(r, 1000));
}

return results.map(r => ({json: r}));
